    carte(pg, "w1").click(); pg.wait_for_selector("[role=dialog]"); pg.wait_for_timeout(200)   # (la section précédente a refermé sa fenêtre)
    esp = lambda: pg.evaluate("(() => { const e = document.querySelector('[data-espion]'); return { n: e.dataset.simulees, h: e.dataset.hashes }; })()")
    ok("ESPION (rôle de la page principale, MÊME magasin de simulations) : avant toute simulation, 0 arme simulée et les perks comptés sont ceux du roll RÉEL (6901, 6912, 6921, 6931)", esp() == {"n": "0", "h": "6901,6912,6921,6931"}, esp())
